  "regulated_action": {
    "target_id": "t0",
    "description": "Modify the shipping address of pending order `#W9810810` to the Houston address (116 Laurel Lane, Suite 319, Houston, TX, 77159) and modify the wristwatch item from `1355937109` (white dial, leather strap) to `9949163720` (black dial, leather strap) using gift card `gift_card_7252880`."
  },
  "applicable_norms": [
    {
      "policy_source_id": "q9",
      "interpretation": "Modify pending order actions (address or items) require explicit user confirmation before execution.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q10",
      "interpretation": "Order status must be 'pending' to modify address or items.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q11",
      "interpretation": "Modify items in a pending order can only be done once and changes the order status to 'pending (items modified)'.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q11",
      "interpretation": "Item modifications must be of the same product type (e.g., wristwatch to wristwatch) and cannot change product categories.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q11",
      "interpretation": "User must provide a payment method for price differences when modifying items.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q11",
      "interpretation": "Gift card must have sufficient balance to cover price differences if used for payment adjustments.",
      "modality": "REQUIRE"
    }
  ],
  "supporting_evidence": [
    {
      "source_id": "h25",
      "actor": "user",
      "role": "confirmation",
      "fact": "User explicitly confirmed the modifications with 'Yes, that’s right. Please go ahead with those changes.'"
    },
    {
      "source_id": "h12",
      "actor": "system",
      "role": "order_status",
      "fact": "Order `#W9810810` status is 'pending'."
    },
